    'h_stack_full' = '(\u043f\u043e \u0443\u043c\u043e\u043b\u0447\u0430\u043d\u0438\u044e) Nginx + PHP-FPM + MariaDB + Redis + Certbot + \u0443\u0442\u0438\u043b\u0438\u0442\u044b'
