# M CLÉ [arguments…] : texte traduit ({0}, {1}… remplacés par les arguments) ; clé absente : anglais, puis la clé elle-même
function M([string]$Key) {
  $c = $script:Catalog[$script:UiLang]
  if ($c -and $c.ContainsKey($Key)) { $s = $c[$Key] }
  elseif ($script:Catalog['en'].ContainsKey($Key)) { $s = $script:Catalog['en'][$Key] }
  else { return $Key }
  return ([regex]::Unescape($s) -f [object[]]$args)
}

# --- Choix de la langue : option > TOUTPANEL_LANG > $InstallerLang > langue du système > anglais ---------------------
$SupportedLangs = @('en', 'fr', 'de', 'es', 'it', 'pt', 'nl', 'ru', 'zh', 'ar')
$script:UiLang = 'en'
$script:LangSrc = 'default'
$LangBad = ''
function Select-Lang([string]$Value, [string]$From) {
  $v = ("$Value".ToLower() -split '[-_.@]')[0]
  if ($v -and $SupportedLangs -contains $v) { $script:UiLang = $v; $script:LangSrc = $From; return $true }
  return $false
}
$langOpt = $Lang
if (-not $langOpt) { foreach ($l in $SupportedLangs) { if ($PSBoundParameters.ContainsKey($l) -and $PSBoundParameters[$l]) { $langOpt = $l } } }
if ($langOpt) { if (-not (Select-Lang $langOpt 'option')) { $LangBad = $langOpt } }
elseif ($env:TOUTPANEL_LANG) { if (-not (Select-Lang $env:TOUTPANEL_LANG 'env')) { $LangBad = $env:TOUTPANEL_LANG } }
elseif ($InstallerLang) { if (-not (Select-Lang $InstallerLang 'file')) { $LangBad = $InstallerLang } }
else {
  $sysLang = ''
  try { $sysLang = (Get-Culture).TwoLetterISOLanguageName } catch {}
  [void](Select-Lang $sysLang 'system')
}
# accents et écritures non latines : sortie console en UTF-8 (sans effet ou impossible dans certains hôtes : ignoré)
try { [Console]::OutputEncoding = New-Object System.Text.UTF8Encoding($false) } catch {}

function Log($m) { Write-Host "[ToutPanel] $m" -ForegroundColor Green }
function Warn($m) { Write-Host "[ToutPanel] $m" -ForegroundColor Yellow }
function Step($m) { Write-Host "`n==> $m" -ForegroundColor Cyan }
function Download($url, $dest) { Log (M 'downloading' $url); (New-Object Net.WebClient).DownloadFile($url, $dest) }
# Largeur d'affichage (caractères chinois : 2 colonnes) pour aligner « libellé : valeur »
function Get-DisplayWidth([string]$s) {
  $w = 0
  foreach ($ch in $s.ToCharArray()) {
    $c = [int]$ch
    if (($c -ge 0x1100 -and $c -le 0x115F) -or ($c -ge 0x2E80 -and $c -le 0xA4CF) -or ($c -ge 0xAC00 -and $c -le 0xD7A3) -or
        ($c -ge 0xF900 -and $c -le 0xFAFF) -or ($c -ge 0xFE30 -and $c -le 0xFE4F) -or ($c -ge 0xFF00 -and $c -le 0xFF60) -or
        ($c -ge 0xFFE0 -and $c -le 0xFFE6)) { $w += 2 } else { $w += 1 }
  }
  return $w
}
function Kv([int]$Width, [string]$Label, [string]$Value) { return $Label + (' ' * [Math]::Max(1, $Width - (Get-DisplayWidth $Label))) + ': ' + $Value }

if ($LangBad) { Warn (M 'lang_unknown' $LangBad ($SupportedLangs -join ' ')) }

function Show-Usage {
  $o = { param($a, $b) Write-Host ("  " + $a.PadRight(30) + " " + $b) }
  Write-Host "ToutPanel - install.ps1"
  Write-Host ""
  Write-Host (M 'usage_title')
  Write-Host "  iwr -useb https://raw.githubusercontent.com/qu3ntin01/toutpanel/main/install.ps1 | iex"
  Write-Host "  `$env:TOUTPANEL_LANG = 'fr'; iwr -useb https://raw.githubusercontent.com/qu3ntin01/toutpanel/main/install.ps1 | iex"
  Write-Host "  .\install.ps1 [options]"
  Write-Host ""
  Write-Host (M 'options_title')
  & $o "-Port N" (M 'h_port')
  & $o "-Home DIR" (M 'h_home' "$env:SystemDrive\toutpanel")
  & $o "-Stack" (M 'h_stack_win')
  & $o "-Update" (M 'h_update_win')
  & $o "-Reinstall" (M 'h_reinstall')
  & $o "-Uninstall" (M 'h_uninstall_win')
  & $o "-Yes" (M 'h_yes')
  & $o "-Username NAME" (M 'h_username')
  & $o "-Password PASS" (M 'h_password')
  & $o "-Entrance /PATH" (M 'h_entrance')
  & $o "-Source DIR" (M 'h_source')
  & $o "-Branch NAME" (M 'h_branch')
  & $o "-Lang CODE" (M 'h_lang')
  & $o "-En -Fr -De -Es -It -Pt -Nl -Ru -Zh -Ar" ""
  & $o "" (M 'h_lang_short')
  & $o "-Help" (M 'h_help')
  Write-Host ""
  Write-Host (M 'help_menu')
  Write-Host (M 'help_lang' "(Get-Culture).TwoLetterISOLanguageName")
  Write-Host (M 'help_env' "TOUTPANEL_LANG, TOUTPANEL_REPO")
}
if ($Help) { Show-Usage; exit 0 }

$isAdmin = ([Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)
if (-not $isAdmin) { Write-Error (M 'need_admin'); exit 1 }
$build = [Environment]::OSVersion.Version.Build
if ($build -lt 14393) { Write-Error (M 'win_build' $build); exit 1 }
$tmp = Join-Path $env:TEMP "toutpanel-install"; New-Item -ItemType Directory -Force -Path $tmp | Out-Null

# --- Présentation, état et menu ---------------------------------------------------
function Banner {
  Write-Host ""
  # dessin en ASCII dans le fichier (lisible par PowerShell 5.1 sans BOM), caractères de bloc restitués à l'affichage
  $art = @(
    "  ########q ######q ##q   ##q########q######q  #####q ###q   ##q#######q##q     ",
    "  b==##p==d##p===##q##I   ##Ib==##p==d##p==##q##p==##q####q  ##I##p====d##I     ",
    "     ##I   ##I   ##I##I   ##I   ##I   ######pd#######I##p##q ##I#####q  ##I     ",
    "     ##I   ##I   ##I##I   ##I   ##I   ##p===d ##p==##I##Ib##q##I##p==d  ##I     ",
    "     ##I   b######pdb######pd   ##I   ##I     ##I  ##I##I b####I#######q#######q",
    "     b=d    b=====d  b=====d    b=d   b=d     b=d  b=db=d  b===db======db======d")
  $i = 0
  foreach ($line in $art) {
    $line = $line.Replace('#', [char]0x2588).Replace('q', [char]0x2557).Replace('p', [char]0x2554).Replace('=', [char]0x2550).Replace('I', [char]0x2551).Replace('d', [char]0x255D).Replace('b', [char]0x255A)
    Write-Host $line -ForegroundColor $(if ($i -lt 3) { "Blue" } else { "Cyan" }); $i++
  }
  Write-Host ("  " + (M 'tagline')) -ForegroundColor White
  Write-Host ("  https://toutpanel.com " + [char]0x00B7 + " https://github.com/qu3ntin01/toutpanel") -ForegroundColor DarkGray
  Write-Host ("  " + (M 'lang_line' (M 'lang_name') (M "lang_src_$($script:LangSrc)") '-Lang')) -ForegroundColor DarkGray
  Write-Host ""
}
function Intro {
  $b = "   " + [char]0x2022 + " "
  Write-Host ("  " + (M 'intro_title')) -ForegroundColor White
  Write-Host ("  " + (M 'intro_lead'))
  Write-Host ($b + (M 'intro_b1' 'Nginx / IIS'))
  Write-Host ($b + (M 'intro_b2'))
  Write-Host ($b + (M 'intro_b3'))
  Write-Host ($b + (M 'intro_b4'))
  Write-Host ("  " + (M 'intro_end' (M 'intro_stack_win')))
  Write-Host ""
}
$Existing = Test-Path "$PanelHome\data\settings.json"
$ExistingVersion = ""
if ($Existing -and (Test-Path "$PanelHome\venv\Scripts\toutpanel.exe")) { try { $ExistingVersion = (& "$PanelHome\venv\Scripts\toutpanel.exe" --version 2>$null | Select-Object -First 1) } catch {} }
Banner
if ($Existing) { Write-Host ("  " + [char]0x25CF + " " + (M 'state_existing' $PanelHome $(if ($ExistingVersion) { $ExistingVersion } else { M 'unknown' }))) -ForegroundColor Green }
else { Write-Host ("  " + [char]0x25CB + " " + (M 'state_none' $PanelHome)) -ForegroundColor Yellow }
Write-Host ""

$interactive = (-not $Yes) -and (-not $Update) -and (-not $Reinstall) -and (-not $Uninstall) -and [Environment]::UserInteractive -and (-not [Console]::IsInputRedirected)
if ($interactive) {
  Intro
  Write-Host ("  " + (M 'menu_title')) -ForegroundColor White
  if ($Existing) {
    Write-Host "   1) $(M 'm_update')  ($(M 'm_update_d'))"
    Write-Host "   2) $(M 'm_reinstall')  ($(M 'm_reinstall_d' $PanelHome))"
    Write-Host "   3) $(M 'm_uninstall')  ($(M 'm_uninstall_d'))"
    Write-Host "   4) $(M 'm_quit')"
  } else {
    Write-Host "   1) $(M 'm_install')  ($(M 'm_install_d_win'))"
    Write-Host "   2) $(M 'm_panel_only')  ($(M 'm_panel_only_d'))"
    Write-Host "   3) $(M 'm_quit')"
  }
  $choice = Read-Host ("  " + (M 'menu_choice_win' '1'))
  if (-not $choice) { $choice = "1" }
  Write-Host ""
  if ($Existing) {
    switch ($choice) { "1" { $Update = $true } "2" { $Reinstall = $true } "3" { $Uninstall = $true } default { Write-Host ("  " + (M 'goodbye')); exit 0 } }
  } else {
    switch ($choice) { "1" { $Stack = $true } "2" { $Stack = $false } default { Write-Host ("  " + (M 'goodbye')); exit 0 } }
  }
}

# --- Désinstallation -------------------------------------------------------------
if ($Uninstall) {
  Step (M 'st_uninstall')
  if (-not (Test-Path $PanelHome)) { Write-Host ("  " + (M 'un_nothing' $PanelHome)); exit 0 }
  Write-Host ("  " + (M 'un_remove_win' $PanelHome))
  Write-Host ("  " + (M 'un_keep_win' "$PanelHome\wwwroot"))
  if (-not $Yes) {
    # le mot affiché dans la langue choisie, ou « yes » / « oui » quelle que soit la langue
    $word = M 'confirm_word'
    $confirm = Read-Host ("  " + (M 'un_confirm_win' $word))
    if ($confirm -ne $word -and $confirm -ne "yes" -and $confirm -ne "oui") { Write-Host ("  " + (M 'un_cancelled')); exit 0 }
  }
  schtasks /End /TN ToutPanel 2>$null | Out-Null
  schtasks /Delete /F /TN ToutPanel 2>$null | Out-Null
  schtasks /Delete /F /TN ToutPanel-Nginx 2>$null | Out-Null
  Get-Process -Name python* -ErrorAction SilentlyContinue | Where-Object { $_.Path -like "$PanelHome\venv\*" } | Stop-Process -Force -ErrorAction SilentlyContinue
  $stamp = Get-Date -Format "yyyyMMdd_HHmmss"
  $archive = "$env:SystemDrive\toutpanel-backup-$stamp.zip"
  $toArchive = @("data", "ssl", "vhost", "templates") | ForEach-Object { Join-Path $PanelHome $_ } | Where-Object { Test-Path $_ }
  if ($toArchive) { Compress-Archive -Path $toArchive -DestinationPath $archive -Force; Log (M 'un_archived' $archive) }
  $www = Join-Path $PanelHome "wwwroot"
  if (Test-Path $www) { $keep = "$env:SystemDrive\toutpanel-wwwroot-$stamp"; Move-Item $www $keep; Log (M 'un_sites_moved' $keep) }
  Remove-Item -Recurse -Force $PanelHome -ErrorAction SilentlyContinue
  $machinePath = [Environment]::GetEnvironmentVariable("Path", "Machine")
  if ($machinePath -like "*$PanelHome\bin*") { [Environment]::SetEnvironmentVariable("Path", (($machinePath -split ";") | Where-Object { $_ -and $_ -ne "$PanelHome\bin" }) -join ";", "Machine") }
  Write-Host ""
  Write-Host ("  " + (M 'un_done')) -ForegroundColor Green
  if (Test-Path $archive) { Write-Host ("  " + (M 'un_archive_win' $archive)) }
  Write-Host ("  " + (M 'un_reinstall_win'))
  Write-Host ""
  exit 0
}

# --- Python -------------------------------------------------------------------
Step (M 'st_python')
function Find-Python {
  foreach ($c in @("py -3", "python", "python3")) {
    try { $v = & cmd /c "$c -c `"import sys;print(sys.version_info>=(3,9))`"" 2>$null; if ($v -eq "True") { return $c } } catch {}
  }
  return $null
}
$py = Find-Python
if (-not $py) {
  Log (M 'python_installing' $PythonVersion)
  $exe = Join-Path $tmp "python-installer.exe"
  Download "https://www.python.org/ftp/python/$PythonVersion/python-$PythonVersion-amd64.exe" $exe
  Start-Process -FilePath $exe -ArgumentList "/quiet InstallAllUsers=1 PrependPath=1 Include_test=0 Include_launcher=1" -Wait
  $env:Path = [Environment]::GetEnvironmentVariable("Path", "Machine") + ";" + [Environment]::GetEnvironmentVariable("Path", "User")
  $py = Find-Python
  if (-not $py) { Write-Error (M 'python_missing'); exit 1 }
}
Log (M 'python_found' "$(& cmd /c "$py --version")")

# --- Installation existante ? → mise à jour --------------------------------------
if (-not $Reinstall -and (Test-Path "$PanelHome\data\settings.json")) { $Update = $true }
if ($Update) {
  if (-not (Test-Path "$PanelHome\data\settings.json")) { Write-Error (M 'no_install_update' $PanelHome '-Update'); exit 1 }
  Log (M 'update_detected' $PanelHome)
  $bk = Join-Path $PanelHome ("backup\panel-update-" + (Get-Date -Format "yyyyMMdd_HHmmss"))
  New-Item -ItemType Directory -Force -Path $bk | Out-Null
  Copy-Item -Recurse -Force "$PanelHome\data" $bk
  Log (M 'data_backed_up' $bk)
  try { $Port = (Get-Content "$PanelHome\data\settings.json" -Raw | ConvertFrom-Json).panel_port } catch {}
  schtasks /End /TN ToutPanel 2>$null | Out-Null
}

# --- Sources ------------------------------------------------------------------
Step ($(if ($Update) { M 'st_update_panel' $PanelHome } else { M 'st_install_panel' $PanelHome }))
New-Item -ItemType Directory -Force -Path $PanelHome, "$PanelHome\wwwroot", "$PanelHome\data" | Out-Null
if (-not $Source -and $PSScriptRoot -and ((Test-Path (Join-Path $PSScriptRoot "pyproject.toml")) -or ((Test-Path (Join-Path $PSScriptRoot "version.json")) -and (Test-Path (Join-Path $PSScriptRoot "dist"))))) { $Source = $PSScriptRoot }
if (-not $Source) {
  $zip = Join-Path $tmp "toutpanel.zip"
  $repo = if ($env:TOUTPANEL_REPO) { $env:TOUTPANEL_REPO.TrimEnd("/") -replace "\.git$", "" } else { "https://github.com/qu3ntin01/toutpanel" }
  Download "$repo/archive/refs/heads/$Branch.zip" $zip
  $srcDir = Join-Path $PanelHome "src"
  if (Test-Path $srcDir) { Remove-Item -Recurse -Force $srcDir }
  $extract = Join-Path $tmp "src-extract"
  if (Test-Path $extract) { Remove-Item -Recurse -Force $extract }
  Expand-Archive -Path $zip -DestinationPath $extract -Force
  $inner = Get-ChildItem -Path $extract -Directory | Select-Object -First 1
  if (-not $inner) { throw (M 'archive_empty') }
  Move-Item $inner.FullName $srcDir
  $Source = $srcDir
}
if (-not (Test-Path "$PanelHome\venv\Scripts\python.exe")) { & cmd /c "$py -m venv `"$PanelHome\venv`"" }
$venvPy = "$PanelHome\venv\Scripts\python.exe"
& $venvPy -m pip install --quiet --upgrade pip wheel
# Mode d'installation : sources (pyproject.toml : dépôt de développement) ou roue précompilée (dist\ : dépôt public)
if (Test-Path (Join-Path $Source "pyproject.toml")) {
  Log (M 'installing_source' $Source)
  & $venvPy -m pip install --quiet --upgrade "$Source"
  if ($LASTEXITCODE -ne 0) { Write-Error (M 'pip_failed' $LASTEXITCODE); exit 1 }
} elseif (Test-Path (Join-Path $Source "dist")) {
  # roue du Python de l'environnement : toutpanel-<version>-cp3XY-none-any.whl (bytecode portable, aucune source)
  $pyTag = (& $venvPy -c "import sys;print('cp%d%d' % sys.version_info[:2])").Trim()
  $pyVer = (& $venvPy -c "import sys;print('%d.%d' % sys.version_info[:2])").Trim()
  $wheel = Get-ChildItem -Path (Join-Path $Source "dist") -Filter "toutpanel-*-$pyTag-none-any.whl" -ErrorAction SilentlyContinue | Sort-Object Name | Select-Object -Last 1
  if (-not $wheel) {
    $supported = (Get-ChildItem -Path (Join-Path $Source "dist") -Filter "toutpanel-*-cp3*-none-any.whl" -ErrorAction SilentlyContinue | ForEach-Object { if ($_.Name -match "-cp3(\d+)-none-any\.whl$") { "3." + $Matches[1] } } | Sort-Object { [int]($_ -split "\.")[1] } -Unique) -join " "
    Write-Error ((M 'no_wheel' $pyVer "$Source\dist") + " " + (M 'wheel_supported' $(if ($supported) { $supported } else { M 'none' })) + " " + (M 'no_wheel_hint_win' "$PanelHome\venv"))
    exit 1
  }
  $sums = Join-Path $Source "dist\SHA256SUMS"
  if (Test-Path $sums) {   # intégrité de la roue (sommes publiées avec la version)
    $expected = (Get-Content $sums | Where-Object { $_ -match ("\s" + [regex]::Escape($wheel.Name) + "$") } | Select-Object -First 1) -split "\s+" | Select-Object -First 1
    $actual = (Get-FileHash -Algorithm SHA256 $wheel.FullName).Hash.ToLower()
    if ($expected -and $expected.ToLower() -ne $actual) { Write-Error (M 'checksum_bad' $wheel.Name); exit 1 }
  }
  Log (M 'installing_wheel' $wheel.Name $pyVer)
  & $venvPy -m pip install --quiet --upgrade $wheel.FullName
  if ($LASTEXITCODE -ne 0) { Write-Error (M 'pip_failed' $LASTEXITCODE); exit 1 }
  # pip ne réinstalle pas de lui-même une roue dont le numéro de version n'a pas changé (branche dev) : réinstallation forcée du seul paquet
  & $venvPy -m pip install --quiet --upgrade --no-deps --force-reinstall $wheel.FullName
  if ($LASTEXITCODE -ne 0) { Write-Error (M 'pip_reinstall_failed' $LASTEXITCODE); exit 1 }
} else {
  Write-Error (M 'repo_incomplete' $Source 'dist\'); exit 1
}
[Environment]::SetEnvironmentVariable("TOUTPANEL_HOME", $PanelHome, "Machine")
$env:TOUTPANEL_HOME = $PanelHome
$tp = "$PanelHome\venv\Scripts\toutpanel.exe"

# --- Pile web (optionnelle, sans winget) --------------------------------------
if ($Stack) {
  Step (M 'st_nginx_win' $NginxVersion)
  if (-not (Test-Path "C:\nginx\nginx.exe")) {
    $nz = Join-Path $tmp "nginx.zip"
    Download "https://nginx.org/download/nginx-$NginxVersion.zip" $nz
    Expand-Archive -Path $nz -DestinationPath $tmp -Force
    Move-Item (Join-Path $tmp "nginx-$NginxVersion") "C:\nginx"
  }
  New-Item -ItemType Directory -Force -Path "C:\nginx\conf\vhost", "C:\nginx\conf\conf.d" | Out-Null
  $conf = Get-Content "C:\nginx\conf\nginx.conf" -Raw
  if ($conf -notmatch "include vhost/\*\.conf;") { $conf = $conf -replace "(?m)^(\s*http\s*\{)", "`$1`r`n    include vhost/*.conf;`r`n    include conf.d/*.conf;" ; Set-Content "C:\nginx\conf\nginx.conf" $conf -Encoding ASCII }
  schtasks /Delete /F /TN ToutPanel-Nginx 2>$null | Out-Null
  # le répertoire de travail doit être C:\nginx : on passe par un lanceur
  "@echo off`r`ncd /d C:\nginx`r`nstart `"`" nginx.exe" | Set-Content "C:\nginx\start-nginx.cmd" -Encoding ASCII
  schtasks /Create /F /SC ONSTART /RU SYSTEM /RL HIGHEST /TN ToutPanel-Nginx /TR "C:\nginx\start-nginx.cmd" | Out-Null
  Start-Process -FilePath "C:\nginx\start-nginx.cmd" -WindowStyle Hidden
  Log (M 'nginx_installed' 'C:\nginx')

  Step (M 'st_php_win' $PhpVersion)
  & $tp php install $PhpVersion --extensions mysql,curl,gd,intl,mbstring,xml,zip,opcache
  if ($LASTEXITCODE -ne 0) { Warn (M 'php_failed_win' $PhpVersion) }

  Step (M 'st_mariadb_win' $MariaDBVersion)
  if (-not (Get-Service -Name MariaDB -ErrorAction SilentlyContinue)) {
    $msi = Join-Path $tmp "mariadb.msi"
    Download "https://archive.mariadb.org/mariadb-$MariaDBVersion/winx64-packages/mariadb-$MariaDBVersion-winx64.msi" $msi
    $dbPass = -join ((48..57 + 65..90 + 97..122) | Get-Random -Count 20 | ForEach-Object { [char]$_ })
    Start-Process msiexec.exe -ArgumentList "/i `"$msi`" SERVICENAME=MariaDB PASSWORD=$dbPass ALLOWREMOTEROOTACCESS=0 /qn" -Wait
    & $tp dbroot mysql --host 127.0.0.1 --port 3306 --user root --password $dbPass | Out-Null
    $script:DbRootPass = $dbPass
    Log (M 'mariadb_installed_win')
  } else { Log (M 'mariadb_present') }
}

# --- Compte admin et URL sécurisée --------------------------------------------
if ($Update) {
  Step (M 'st_migrate_win')
  & $tp migrate
  $entrance = ""
  try { $entrance = (Get-Content "$PanelHome\data\settings.json" -Raw | ConvertFrom-Json).security_entrance } catch {}
  $setup = [pscustomobject]@{ username = (M 'kept_value'); password = (M 'kept_value'); entrance = $entrance }
} else {
Step (M 'st_admin')
$setupArgs = @("setup", "--json", "--port", "$Port")
if ($Username) { $setupArgs += @("--username", $Username) }
if ($Password) { $setupArgs += @("--password", $Password) }
if ($Entrance) { $setupArgs += @("--entrance", $Entrance) }
$setup = (& $tp @setupArgs) | ConvertFrom-Json
# langue de l'installeur transmise au panel (réglage « language ») : l'interface s'ouvre dans la même langue
try { & $venvPy -c "import sys;from toutpanel import config;config.get_settings().set('language',sys.argv[1])" $script:UiLang 2>&1 | Out-Null } catch {}
}

# --- Pare-feu Windows ---------------------------------------------------------
Step (M 'st_firewall')
foreach ($p in @($Port, 80, 443, 21)) {
  netsh advfirewall firewall delete rule name="ToutPanel $p" | Out-Null
  netsh advfirewall firewall add rule name="ToutPanel $p" dir=in action=allow protocol=TCP localport=$p | Out-Null
}

# --- Démarrage automatique (tâche planifiée SYSTEM) ---------------------------
Step (M 'st_task')
schtasks /End /TN ToutPanel 2>$null | Out-Null
schtasks /Delete /F /TN ToutPanel 2>$null | Out-Null
schtasks /Create /F /SC ONSTART /RU SYSTEM /RL HIGHEST /TN ToutPanel /TR "`"$venvPy`" -m toutpanel run" | Out-Null
schtasks /Run /TN ToutPanel | Out-Null
Log (M 'task_created')

# --- Raccourci CLI ------------------------------------------------------------
$binDir = "$PanelHome\bin"; New-Item -ItemType Directory -Force -Path $binDir | Out-Null
"@echo off`r`nset TOUTPANEL_HOME=$PanelHome`r`n`"$tp`" %*" | Set-Content "$binDir\toutpanel.cmd" -Encoding ASCII
$machinePath = [Environment]::GetEnvironmentVariable("Path", "Machine")
if ($machinePath -notlike "*$binDir*") { [Environment]::SetEnvironmentVariable("Path", "$machinePath;$binDir", "Machine") }

# --- Récapitulatif ------------------------------------------------------------
$localIp = (Get-NetIPAddress -AddressFamily IPv4 -ErrorAction SilentlyContinue | Where-Object { $_.IPAddress -notlike "127.*" -and $_.IPAddress -notlike "169.254.*" } | Select-Object -First 1).IPAddress
if (-not $localIp) { $localIp = "localhost" }
$publicIp = ""
try { $publicIp = (Invoke-RestMethod -Uri "https://api.ipify.org" -TimeoutSec 5 -ErrorAction Stop).ToString().Trim() } catch {}
if ($publicIp -notmatch '^[0-9.]+$') { $publicIp = "" }
$ip = if ($publicIp) { $publicIp } else { $localIp }
$url = "http://$ip`:$Port$($setup.entrance)"
$urlLocal = if ($publicIp -and $publicIp -ne $localIp) { "http://$localIp`:$Port$($setup.entrance)" } else { "" }
# assistant de configuration (#/setup) : lien 24 h à usage unique pour changer l'adresse, l'utilisateur et le mot de passe générés
$setupUrl = if (-not $Update -and $setup.setup_token) { "$url#/setup?token=$($setup.setup_token)" } else { "" }
# libellés dans la langue de l'installeur (en français, ceux que l'assistant de configuration met à jour)
$info = @(
  (M 'info_title' (Get-Date -Format 'yyyy-MM-dd HH:mm')),
  (Kv 18 (M 'lbl_url') $url),
  (Kv 18 (M 'lbl_url_local') $(if ($urlLocal) { $urlLocal } else { $url })),
  (Kv 18 (M 'lbl_user') $setup.username),
  (Kv 18 (M 'lbl_pass') $setup.password),
  (Kv 18 (M 'lbl_entrance') $setup.entrance),
  (Kv 18 (M 'lbl_dir') $PanelHome)
)
if ($setupUrl) { $info += (Kv 18 (M 'lbl_setup') $setupUrl); $info += ("  " + (M 'setup_note_file')) }
if ($script:DbRootPass) { $info += (Kv 18 (M 'lbl_mariadb') $script:DbRootPass) }
$info | Set-Content "$PanelHome\data\install-info.txt" -Encoding UTF8

Write-Host ""
Write-Host "=================================================================" -ForegroundColor Green
Write-Host ("  " + (M 'done_install')) -ForegroundColor Green
Write-Host "=================================================================" -ForegroundColor Green
Write-Host ("  " + (Kv 17 (M 'lbl_url') $url))
if ($urlLocal) { Write-Host ("  " + (Kv 17 (M 'lbl_url_local') "$urlLocal   $(M 'from_network')")) }
Write-Host ("  " + (Kv 17 (M 'lbl_user') $setup.username))
Write-Host ("  " + (Kv 17 (M 'lbl_pass') $setup.password))
if ($setupUrl) {
  Write-Host ""
  Write-Host ("  " + (Kv 17 (M 'lbl_setup') $setupUrl))
  Write-Host ("  " + (M 'setup_note'))
  Write-Host ("  " + (M 'setup_new_link'))
}
if ($script:DbRootPass) { Write-Host ("  " + (Kv 17 (M 'lbl_mariadb') $script:DbRootPass)) }
Write-Host ""
Write-Host ("  " + (M 'saved_in' "$PanelHome\data\install-info.txt"))
Write-Host ("  " + (M 'entrance_note'))
Write-Host ("  " + (Kv 17 (M 'lbl_commands') "toutpanel info | check | passwd | entrance | port | restart | setup-link | php install 8.2"))
